            "sku": row[1],
            "quantity": row[2],
            "status": row[3],
            "result": json.loads(row[4]) if row[4] else None,
        }

    def waiting_count(self):
        with self._connect() as conn:
            return conn.execute("SELECT COUNT(*) FROM queue").fetchone()[0]
